class WithEffects(HigherOrderOperator):
    """
    with_effects(token, op, args, kwargs) -> (new_token, op_results)

    This HOP helps ensure ordering between side effectful ops like prints or ops
    using torchbind objects. This is needed to ensure a traced graph from
    the user's code is correctly ordered.
    """
    def __init__(self, op: torch._ops.OpOverload, effect: _EffectType) -> None:
        self.op = op
        self.effect = effect

    def __call__(self, token: Any, *args: Any, **kwargs: Any) -> Tuple[Any, Any]:
        # Apply the side effect and return the new token and results
        # This is a simplified example; actual implementation would depend on the effect type
