            # This could involve inserting the op into the graph or modifying the token
            # For simplicity, just return the token and a dummy result
            return token, (None,)
        else:
            # For other effects, apply the effect and return the new token and results
            # For example, if the effect is to print, return the token and a message
            return token, (f"Applied effect: {self.effect}",)

    def register_side_effect_op(self, op: torch._ops.OpOverload) -> None:
        SIDE_EFFECTS[op] = self.effect

    @classmethod
    def register(cls, op: torch._ops.OpOverload, effect: _EffectType) -> None:
        instance = cls(op, effect)
        instance.register_side_effect_op(op)

