    # common NA values
    NA_VALUES = set(['-1.#IND', '1.#QNAN', '1.#IND',
                     '-1.#QNAN','1.#INF','-1.#INF', '1.#INF000000',
                     'NA', '#NA', 'NULL', 'NaN', 'nan', ''])
    if na_values is None:
        na_values = NA_VALUES
    else:
