                    num_mlps - num_mlps_to_disable_reduce_scatter
                ) * (num_microbatches - 1)
            self.assertEqual(reduce_scatter_count, expected_reduce_scatter_count)
            reduce_scatter_count = 0
            for param in ref_model.parameters():
