        wrapper.writeline(f"{output_name} = [{','.join(inputs)}] ")

        wrapper.writeline(
            f"{output_name}_work = dist.all_reduce({output_name}, op=_str_to_reduce_op('{str(self.reduce_op)}'), group={output_name}_pg, async_op=True)"
        )
