    def check_skip_condition(node, check_cpu):
        if not isinstance(node, torch.fx.Node):
            return False

        if "val" not in node.meta:
            return False

        for meta in tree_flatten(node.meta["val"])[0]:
            if not isinstance(meta, torch._subclasses.FakeTensor):
