                return True

        return False

    # only skip codegen if there is a cpu output, not input
    for arg in tree_flatten((node.args, node.kwargs))[0]:
        if check_skip_condition(arg, check_cpu=False):
            return True

    return check_skip_condition(node, check_cpu=True)

