            x = TestTensor(inp)
            torch._dynamo.mark_dynamic(x, 0)
            y = TestTensor(inp)
            torch._dynamo.mark_dynamic(y, 0)
            compiled_fn = torch.compile(fn, backend="aot_eager", fullgraph=True)
