def nnmodule_has_hooks(
    mod,
    check_forward_hooks=False,
    check_backward_hooks=False,
    check_state_dict_hooks=False,
):
    """
    Sometimes its useful to differentiate between types of hooks such as forward/backward/pre
    hooks executed during module.__call__, and state_dict hooks which are executed separately.
    """
    hook_dicts_to_check = []
    check_all_hooks = (
        not check_forward_hooks
        and not check_backward_hooks
        and not check_state_dict_hooks
    )
    if check_forward_hooks or check_all_hooks:
        hook_dicts_to_check.extend(
            [
                "_forward_pre_hooks",
                "_forward_hooks",
            ]
        )
    if check_backward_hooks or check_all_hooks:
        hook_dicts_to_check.extend(
            [
                "_backward_pre_hooks",
                "_backward_hooks",
            ]
        )
    if check_state_dict_hooks:
        hook_dicts_to_check.extend(
            [
                "_state_dict_pre_hooks",
                "_state_dict_hooks",
                "_load_state_dict_pre_hooks",
                "_load_state_dict_post_hooks",
            ]
        )
    return any(len(getattr(mod, x)) > 0 for x in hook_dicts_to_check if hasattr(mod, x))

def cleanup_graph(self):
    """
    Remove this pattern from the graph:
        torch._C._set_grad_enabled(False)
        torch._C._set_grad_enabled(True)
    """
    nodes = list(self.graph.nodes)
    grad_enabled = torch.is_grad_enabled()
    for node1, node2 in zip(nodes, nodes[1:]):
        if (
            node1.target is torch._C._set_grad_enabled
            and tuple(node1.args) == (not grad_enabled,)
            and not node1._erased
        ):
            grad_enabled = node1.args[0]
            if (
                node2.target is torch._C._set_grad_enabled
                and tuple(node2.args) == (not grad_enabled,)
                and not node2._erased
            ):
                grad_enabled = node2.args[0]
                self.graph.erase_node(node1)
                self.graph.erase_node(node2)

